// features/lifecycle.feature: Resubmitting without replacing the rejected document is refused
import { expect, expectStatus, test } from "../../fixtures";

test(
  "resubmitting without replacing the rejected w9 is refused with documents_incomplete",
  { tag: "@LIF-04" },
  async ({ apiAs, factory }) => {
    // Arrange
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const { vendor, extractions } = await factory.vendorInReview();
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
        data: { decision: "reject", note: "Tax ID does not match" },
      }),
      200,
    );

    // Act
    const response = await member.post(`/api/vendors/${vendor.id}/submit`);

    // Assert
    const body = await expectStatus(response, 409);
    expect(body.error.code).toBe("documents_incomplete");
    expect(body.error.missing_kinds).toEqual(["w9"]);
  },
);
